def usage_report(self, user_id: str, month: str) -> dict:
    # Aggregate successful requests and charged failed attempts.
    entries = [e for e in self.entries if e.user_id == user_id and e.month == month]
    report = {
        "requests": sum(1 for e in entries if e.status == "ok"),
        "failed_attempts": sum(1 for e in entries if e.status == "failed_attempt"),
        "prompt_tokens": sum(e.usage.prompt_tokens for e in entries),
        "cached_tokens": sum(e.usage.cached_tokens for e in entries),
        "completion_tokens": sum(e.usage.completion_tokens for e in entries),
        "cost_usd": sum((e.cost for e in entries), Decimal("0")),
    }
    return report

def top_spenders(self, month: str, n: int) -> List[Tuple[str, Decimal]]:
    # Sum total cost per user for the given month.
    totals: Dict[str, Decimal] = {}
    for e in self.entries:
        if e.month != month:
            continue
        totals[e.user_id] = totals.get(e.user_id, Decimal("0")) + e.cost
    # Exclude zero‑cost users.
    items = [(uid, cost) for uid, cost in totals.items() if cost != Decimal("0")]
    # Sort by cost descending, then user_id ascending.
    items.sort(key=lambda x: (-x[1], x[0]))
    return items[:n]

